                  <label ng-model="matricula.estado" uib-btn-radio="'FORM'" ng-click="$ctrl.set_estado_next_matricula($ctrl.alumno)" uib-tooltip="Formulario vendido" class="btn btn-success btn-prematriculas">Formulario</label>
